#!/usr/bin/env node
// GENERATED by scripts/build-runtime.mjs from runtime/src/dispatch.mjs. Do not edit.
// Repo-root hook dispatcher (written by convert.mjs as <repo>/n8m-hook.mjs). Claude Code loads
// only the root .claude/settings.json of a repository, so a repo holding several migrated
// workflow folders gets one root settings file (the union of the folders' allowlists) whose
// hooks run this file. It finds the folder the call belongs to and runs that folder's own
// runtime/hook.mjs, which does all the checking:
//   pre:  the folder with an outstanding request for this tool (a run in progress, or a
//         driver-level request such as an alert) whose arguments match once placeholders are
//         expanded; else the first folder with any outstanding request (its hook denies with
//         the reason); with no run in progress anywhere, the call is denied.
//   post: the folder whose pre hook recorded this tool_use_id, else the matching request.
// Fails closed like the folder hook: an error in pre denies the call.

import { readFileSync, readdirSync, existsSync, realpathSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = dirname(fileURLToPath(import.meta.url));
const out = (o) => process.stdout.write(JSON.stringify(o) + "\n");
const deny = (reason) => out({ hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: reason } });

export function workflowFolders(root = ROOT) {
  return readdirSync(root, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !d.name.startsWith(".") && existsSync(join(root, d.name, "definition.json")) && existsSync(join(root, d.name, "runtime", "hook.mjs")))
    .map((d) => join(root, d.name));
}

export async function pickFolder(which, input, root = ROOT) {
  const safeId = String(input.tool_use_id ?? "last").replace(/[^\w-]/g, "_");
  let fallback = null;
  for (const folder of workflowFolders(root)) {
    const drv = await import(pathToFileURL(join(folder, "runtime", "driver.mjs")).href);
    if (which === "post" && existsSync(join(drv.paths(folder, input.cwd ?? process.cwd()).n8m, "calls", `${safeId}.json`))) return folder;
    const P = drv.paths(folder, input.cwd ?? process.cwd());
    const { list } = drv.outstanding(P);
    const pending = list.filter((x) => x.req.kind === "tool" && !drv.hasResult(P, x.handle));
    if (!pending.length) continue;
    fallback ??= folder;
    const task = drv.loadTask(P);
    for (const x of pending) if (drv.toolName(task, x.req) === input.tool_name && drv.deepEqual(drv.expandArgs(input.tool_input ?? {}, x.handle, x.req.args ?? {}), x.req.args ?? {})) return folder;
  }
  return which === "pre" ? fallback : null;
}

const isMain = process.argv[1] && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]);
if (isMain) {
  const which = process.argv[2];
  try {
    const input = JSON.parse(readFileSync(0, "utf8") || "{}");
    const folder = await pickFolder(which, input);
    if (!folder) {
      if (which === "pre") deny(`${input.tool_name} is not a request of any workflow run in progress here. Do not call tools on your own: run the runner's next command and do only what it says.`);
      process.exit(0);
    }
    const { runHook } = await import(pathToFileURL(join(folder, "runtime", "hook.mjs")).href);
    await runHook(which, input, folder);
    process.exit(0);
  } catch (e) {
    if (which === "pre") {
      deny(`The runner's hook failed (${e.message}); the call is refused.`);
      process.exit(0);
    }
    process.stderr.write(`n8m hook: ${e.message}\n`);
    process.exit(1);
  }
}
